/* List Items */
richlistitem {
  &[state="disconnected"]:not([selected]) {
    color: #999;
  }

  &[dragover="down"] {
    border-block-end: 3px solid var(--selected-item-color);
  }

  &[dragover="up"] {
    border-block-start: 3px solid var(--selected-item-color);
  }

  & .account-buttons {
    margin-block-start: 2px;

    /* When the error message was too long, the buttons were too small */
    & button {
      min-block-size: 1.8em;
    }
  }

  &:not([selected]) .account-buttons {
    display: none;
  }

  &:not([state="connected"]) .connected,
  &:not([state="connecting"]) .connecting,
  &:not([state="disconnected"]) .disconnected,
  &:not([state="disconnecting"]) .disconnecting,
  &:not([error="true"]) .error,
  &:not([state="disconnected"]) .error,
  &[error="true"] .disconnected,
  &[selected]:not([state="disconnected"]) .connectButton,
  &[selected][state="disconnected"] .disconnectButton,
  &[selected][state="disconnecting"] .disconnectButton,
  &:not([selected]) .addException,
  &:not([selected]) .autoSignOn,
  &:not([reconnectPending="true"]) description[anonid="reconnect"] {
    display: none;
  }

  &[state="disconnected"] .accountIcon {
    opacity: 0.3;
  }

